<!DOCTYPE html>
<html lang="en">

<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    @vite('resources/css/app.css')
    <title>Document</title>
</head>
<style>
    /* body {
        background: linear-gradient(-30deg,#349b97 -20%, #1b3466 80%);
    } */

    .glowing-border {
        position: relative;
        display: inline-block;
        padding: 20px;
        background-color: #fff;
        border-radius: 15px;
        transition: all 0.3s;
        text-align: center;
        overflow: hidden;
    }


    .glowing-border::before,
    .glowing-border::after {
        content: "";
        position: absolute;
    }

    .glowing-border::before {
        width: 200%;
        height: 200%;
        background-color: #fff;
        transition: all 0.3s;
        background-image: conic-gradient(#63e2f8 0deg,
                /* Bright blue color */
                rgba(56, 141, 253, 0.5) 60deg,
                /* Faded blue */
                rgba(56, 141, 253, 0) 180deg,
                /* Fully transparent */
                rgb(44, 160, 255) 180deg,
                /* Faded yellow */
                transparent 240deg);
        inset: -30%;
        z-index: -2;
        animation: border 4s linear infinite;
    }

    @keyframes border {
        to {
            transform: rotateZ(-360deg);
        }
    }

    .glowing-border::after {
        /* Adjust inset as needed */
        --inset: 0.15rem;
        inset: var(--inset);
        border-radius: calc(10px - var(--inset));
        background-color: #fff;
        transition: all 0.3s;
        /* Assuming a border size of 10px */
        z-index: -1;
        /* transition: all 0.35s linear; */
    }

    .glowing-border:hover::after {
        background-color: #fff;
        /* Background color when hovering */
    }
</style>

<body class="overflow-x-hidden">
    @include('layouts.navigation-banner')
